  str_help_season1_title_503 = "Síntesis de elementos",
  str_help_season1_title_504 = "Huella de recuerdos",
  str_help_season1_title_505 = "Memoria sónica",
  str_help_season1_disc_101 = "El Despertar en la Tormenta ha llegado. En un sueño profundo, el sueño se repite, repitiéndose a sí mismo.",
  str_help_season1_disc_102 = "Guía a Eve en utilizar sus puntos de ingenio para conquistar el Omen dentro del sueño. Al resolverlo, obtendrás acceso a Metamorpha y Sediment Shards. Estos se pueden cambiar por una variedad de recompensas en el Memory Workshop, incluido el atuendo Once Upon a Springtime.",
  str_help_season1_disc_103 = "Termina las misiones detalladas en los Fragmentos de memoria para ganar Lumamber y descubre historias ocultas sobre Eve.",
  str_help_season1_disc_104 = "Completa misiones dentro del mundo de los sueños para adquirir el Stand By Me Set.",
  str_help_season1_disc_105 = "Las pequeñas baratijas recogidas en el Sueño están guardadas cuidadosamente aquí por Eve.",
  str_help_season1_disc_201 = "El despertar en la tormenta está sobre nosotros, pero el presagio está obstaculizando el despertar de Eva. Asistir Eve en vencer el Presagio, y ser recompensado generosamente por el éxito. Tenga en cuenta que cada desafío contra el presagio consumirá 1 punto de ingenio.",
  str_help_season1_disc_202 = "Hay dos niveles de dificultad para el desafío Omen: Reverie y Nightmare.\nSi bien Nightmare ofrece una experiencia más desafiante, también brinda recompensas superiores. Si encuentras Nightmare demasiado abrumador, considera probar Reverie primero.\nDentro del mismo desafío Omen, el nivel de estrella alcanzado en Nightmare se sincronizará con Reverie. Lograr una recompensa de autorización de tres estrellas y la primera recompensa clara en Nightmare también le otorgará las recompensas correspondientes de Reverie.",
  str_help_season1_disc_203 = "Visite los detalles del escenario para ver toda la información de Omen relacionada con Awakening in the Storm, donde también puede cambiar entre Reverie y Nightmare.",
  str_help_season1_disc_204 = "Eve mantiene un sentido de racionalidad y claridad, lo que le permite desafiar al Omen en Awakening in the Storm. Los puntos de ingenio se repondrán en 3 puntos cada día a las 05:00 (UTC+0), 00:00 (UTC-5).",
  str_help_season1_disc_205 = "Las Sonrisas Llevan a la Felicidad pueden otorgar potentes beneficios a Eve.\nTriunfa sobre el Presagio bajo la dificultad de Pesadilla para obtener Ondas de Alegría. El artículo puede mejorar el nivel de Las Sonrisas Llevan a la Felicidad.",
  str_help_season1_disc_206 = "Misteriosos tesoros se esconden en Cognova y Nostalix. Puedes ponerlos en la caja de colección de Eve. No pierdas la oportunidad de abrirlos.",
  str_help_season1_disc_207 = "Sandstorm bloqueó el camino de Eve y nubló su corazón. ¡Derrota al presagio que te rodea para disipar la tormenta de arena!",
  str_help_season1_disc_208 = "Eve, siempre obediente, nunca tuvo el deseo de romper la ilusión. Sin embargo, lo que ella aprecia finalmente lo destroza. \"¡Permíteme heredar el arma de mi hermano!\"",
  str_help_season1_disc_209 = "Vaya, un enjambre de Devoradores de Sueños está mordisqueando el sueño de Eve! Si su sueño se desmorona, la pobre Eve podría no despertar nunca más... ¡No podemos permitir que eso suceda!\nDesde las 05:00 del 6 de septiembre hasta las 04:00 del 27 de septiembre, un nuevo enjambre de Devoradores de Sueños emerge a las 05:00 diariamente. Tendrás 5 oportunidades para ahuyentarlos cada día, siendo las primeras 2 expulsiones exitosas las que ofrecen generosas recompensas. La dificultad para expulsar a estos Devoradores de Sueños aumenta con cada intento hasta que se reinicia a las 05:00 del día siguiente.",
  str_help_season1_disc_301 = "El Taller de memoria ofrece una selección de recompensas, entre las que se encuentra el atuendo Once Upon a Springtime.",
  str_help_season1_disc_302 = "Resuelve el Presagio en el sueño para adquirir Metamorfa y Fragmentos de Sedimento.",
  str_help_season1_disc_303 = "Metamorpha se puede cambiar por el atuendo Once Upon a Springtime, y los fragmentos de sedimento se pueden cambiar por varias otras recompensas.",
  str_help_season1_disc_304 = "Después de que cierre el Taller de Memoria, los Metamorpha se convertirán en Fragmentos de Sueño en una proporción de 1:1, mientras que los Fragmentos de Sedimento se cambiarán por Nightium en una proporción de 1:30. Los objetos correspondientes se enviarán directamente a tu Almacén después de una conversión exitosa.",
  str_help_season1_disc_305 = "Después de que cierre el Taller de Memorias, el atuendo Érase una Primavera seguirá disponible en Paisajes de Ensueño Auténticos. En ese momento, podrás intercambiar Fragmentos de Sueño, que se convierten de Metamorpha, por el atuendo.",
  str_help_season1_disc_401 = "Completa las misiones detalladas en los Fragmentos de memoria para ganar Lumamber y descubre historias ocultas sobre Eve.",
  str_help_season1_disc_402 = "Completa las misiones específicas para desbloquear los fragmentos y adquirir Lumamber.",
  str_help_season1_disc_403 = "Al desbloquear los fragmentos, también puede descubrir historias ocultas sobre Eve.",
  str_help_season1_disc_501 = "Las pequeñas baratijas recogidas en el Sueño están guardadas cuidadosamente aquí por Eve.",
  str_help_season1_disc_502 = "Los tesoros sin nombre contienen objetos coleccionables encontrados en el sueño, junto con pistas para adquirir contenido que aún no se ha recolectado.",
  str_help_season1_disc_503 = "Algunos coleccionables interactuarán mágicamente entre sí, creando nuevos objetos misteriosos.",
  str_help_season1_disc_504 = "La huella de los recuerdos documenta los momentos notables vividos en el sueño y las pistas para adquirir contenido que aún no se ha recolectado.",
  str_help_season1_disc_505 = "Sonic Memory captura los fragmentos de melodías escuchadas en el sueño, junto con pistas para adquirir contenido no recolectado.",
  str_help_season2_tab_1 = "Pruebas entre Ondulaciones Doradas",
