  str_help_season2_title_401 = "Lista de verificación",
  str_help_season2_title_402 = "Misión",
  str_help_season2_title_501 = "Exhibición del Caso",
  str_help_season2_title_502 = "Tesoro sin nombre",
  str_help_season2_title_503 = "Huella de recuerdos",
  str_help_season2_title_504 = "Memoria sónica",
  str_help_season2_disc_101 = "¡Silencio, silencio! ¡Los juicios entre ondas doradas ya están en sesión!",
  str_help_season2_disc_102 = "Guía a Irridon en la utilización de sus puntos de ingenio para conquistar el Edge dentro del sueño. Al resolverlo, obtendrás acceso a Contrapesos del Alma y Vela de Justicia, que pueden ser intercambiados por una variedad de recompensas en la Subasta de Pruebas, incluyendo el atuendo Fiat Iustitia.",
  str_help_season2_disc_103 = "Completa las misiones en la lista de verificación para obtener Lumamber como recompensa.",
  str_help_season2_disc_104 = "Completa misiones dentro del mundo de los sueños para adquirir el Stand By Me Set.",
  str_help_season2_disc_105 = "Toda la evidencia recopilada dentro del sueño es categorizada y almacenada metódicamente por Irridon aquí.",
  str_help_season2_disc_201 = "Trials Amongst Golden Ripples ya está en marcha, pero el Edge está obstaculizando el despertar de Irridon. Ayuda a Irridon a enfrentarse al Edge y serás recompensado generosamente por el éxito. Ten en cuenta que cada desafío contra el Edge consumirá 1 punto de ingenio.",
  str_help_season2_disc_202 = "Hay dos niveles de dificultad para el desafío Edge: Reverie y Pesadilla.\nAunque Pesadilla ofrece una experiencia más desafiante, también proporciona recompensas superiores. Si encuentras Pesadilla demasiado abrumadora, considera probar Reverie primero.\nDentro del mismo desafío Edge, el nivel de estrellas alcanzado en Pesadilla se sincronizará con Reverie. Lograr una recompensa de tres estrellas y la recompensa del 1er Clear en Pesadilla también te otorgará las recompensas correspondientes de Reverie.",
  str_help_season2_disc_203 = "Visita los Detalles de la Etapa para ver toda la información de Edge relacionada con Trials Amongst Golden Ripples, donde también puedes cambiar entre Reverie y Pesadilla.",
  str_help_season2_disc_204 = "La clave para mantener un sentido de racionalidad y claridad, permitiéndole desafiar el Edge en Trials Amongst Golden Ripples. El punto de ingenio se repondrá en 3 puntos cada día a las 05:00 (UTC+0), 00:00 (UTC-5).",
  str_help_season2_disc_205 = "El Enfoque de Verdad puede proporcionar una fuerte asistencia en el camino.\nTriunfa sobre el Borde bajo la dificultad de Pesadillas para obtener la Luz de Justicia. El artículo puede mejorar el nivel de Enfoque de Verdad.",
  str_help_season2_disc_206 = "Hay pistas misteriosas y evidencia física en Cognova y Archivos de Casos, que se organizarán en la Exhibición de Casos después de su adquisición.",
  str_help_season2_disc_207 = "La Niebla Mística bloquea el camino de Irridon y nubla su corazón. ¡Derrota a los Edges a tu alrededor para disipar la Niebla Mística!",
  str_help_season2_disc_208 = "Recolecta pistas y utiliza la Escala de Justicia para deducir y resolver los casos que encuentres.",
  str_help_season2_disc_209 = "Oh, no, una multitud de Devoradores de Sueños está mordisqueando el sueño de Irridon. Si su sueño se desmorona, la pobre Irridon podría no despertar nunca más... ¡No podemos permitir que suceda!\nUn nuevo enjambre de Devoradores de Sueños aparece a las 05:00 todos los días. Tendrás 5 oportunidades para ahuyentarlos cada día, siendo las primeras 2 expulsiones exitosas las que ofrecen generosas recompensas. La dificultad para expulsar a estos Devoradores de Sueños aumenta con cada intento hasta que se reinicia a las 05:00 del día siguiente.",
  str_help_season2_disc_301 = "La Subasta de Prueba ofrece una selección de recompensas, entre las cuales se encuentra el atuendo Fiat Iustitia.",
  str_help_season2_disc_302 = "Resuelve el Borde en el sueño para adquirir Contrapesos del Alma y la Vela de la Justicia.",
  str_help_season2_disc_303 = "Los Contrapesos del Alma se pueden intercambiar por el atuendo Fiat Iustitia, y la Vela de Justicia se puede intercambiar por varias otras recompensas.",
  str_help_season2_disc_304 = "Después de que la Subasta de Prueba cierre, los Contrapesos del Alma se convertirán en Fragmentos de Sueño en una proporción de 1:1, mientras que la Vela de Justicia se cambiará por Nightium en una proporción de 1:30. Los artículos correspondientes se enviarán directamente a tu correo.",
  str_help_season2_disc_305 = "Después de que concluya la Subasta de Prueba, el atuendo Fiat Iustitia seguirá disponible en Authentic Dreamscapes. En ese momento, podrás intercambiar Fragmentos de Sueño, que se convierten a partir de Contrapesos del Alma, por el atuendo.",
  str_help_season2_disc_401 = "Completa las misiones en la lista de verificación para obtener Lumamber como recompensa.",
  str_help_season2_disc_402 = "Completa la misión correspondiente para obtener Lumamber como recompensa.",
  str_help_season2_disc_501 = "Toda la evidencia recopilada dentro del sueño es categorizada y almacenada metódicamente por Irridon aquí.",
  str_help_season2_disc_502 = "Los tesoros sin nombre contienen objetos coleccionables encontrados en el sueño, junto con pistas para adquirir contenido que aún no se ha recolectado.",
  str_help_season2_disc_503 = "La huella de los recuerdos documenta los momentos notables vividos en el sueño y las pistas para adquirir contenido que aún no se ha recolectado.",
  str_help_season2_disc_504 = "Sonic Memory captura los fragmentos de melodías escuchadas en el sueño, junto con pistas para adquirir contenido no recolectado.",
